插入操作：
```java
static BST insert(BST t, key ik) {
	if (t == null) {
		return new BST(ik);
	}
	if(t.key > ik) {
		t.left = insert(t.left, ik);
	} else {
	    t.right = insert(t.right, ik);
	}
	return t;
}
```
另外一种繁琐实现
并没有真正信任递归！！！

```java
void insert(int ik) {

    if(this.left != null && this.right != null) {
        if(ik < this.key) {
            this.left.insert(ik);
        } else{
            this.right.insert(ik);
        }
    }
    else if(this.left == null && this.right != null){
        if(ik < this.key){
            this.left = new BST(ik);
        } else {
            this.right.insert(ik);
        }
    }
    else if(this.left != null && this.right == null){
        if(ik > this.key){
            this.right = new BST(ik);
        } else {
            this.left.insert(ik);
        }
    }
    else {
        if(ik < this.key){
            this.left = new BST(ik);
        } else {
            this.right = new BST(ik);
        }
    }
}
```
删除操作：删除 key k -> 用比k小的最大值替换k

我的实现：
```java
void deletewithchilds(BST t,int k)
{
    while(t.key != k){
        if (t.key < k){
          t = t.right;
        } else {
          t = t.left;
        }
      }

    BST p = t.left;
    while( p.right != null && p.right.right != null)
    {
      p = p.right;
    }
    BST fp = p;
    p = p.right;
    if (p == null){
    t.key = fp.key;
    t.left = fp.left;} 
    else{
    t.key = p.key;
    fp.right = p.left;
    }
} 
```

完整版
```
public class BST {
  private int key;
  private BST left;
  private BST right;
  public BST(int ik){
      key = ik;
      left = null;
      right = null;
  }

void deletewithchilds(BST t)
{
    BST p = t.left;
    while( p.right != null && p.right.right != null)
    {
      p = p.right;
    }
    BST fp = p;
    p = p.right;
    if (p == null){
    t.key = fp.key;
    t.left = fp.left;} 
    else{
    t.key = p.key;
    fp.right = p.left;
    }
} 

void delete(int k)
{
  BST t = this;
  BST ft = t;
  while(t.key != k){
    ft = t;
      if (t.key < k){
        t = t.right;
      } else {
        t = t.left;
      }
    }
  if(t.left == null){
    if(t == ft.right){
    ft.right = t.right;}
    else {ft.left = t.right;}
  }
  else if(t.right == null) {
    if(t == ft.right){
    ft.right = t.left;}
    else {ft.left = t.left;}
    }
  else {
    deletewithchilds(t);
    }
}

static BST insert(BST t, int ik) {
    if (t == null) {
        return new BST(ik);
    }
    if(t.key > ik) {
        t.left = insert(t.left, ik);
    } else {
        t.right = insert(t.right, ik);
    }
    return t;
}
  public static void main(String[] args) {
      BST t = new BST(6);
      insert(t,3);
      insert(t,2);
      insert(t,5);
      insert(t,10);
      insert(t,8);
      insert(t,7);
      insert(t,9);
      insert(t,12);
      insert(t,11);
      insert(t,14);    
      t.delete(10);
      t.delete(14);
      t.delete(12);
  }
}
```

